styles:
body { font-family: 'Inter', sans-serif; background-color: #111111; color: #ffffff; }
.text-gradient {
    background: linear-gradient(90deg, #FFE1CC 0%, #FFFFFF 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.bg-card { background-color: #1c1c1c; border: 1px solid rgba(255, 255, 255, 0.1); }
.bg-card-hover:hover { background-color: #252525; transition: all 0.3s ease; }
.hero-glow {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 800px;
    height: 800px;
    background: radial-gradient(circle, rgba(120, 103, 146, 0.15) 0%, rgba(17, 17, 17, 0) 70%);
    z-index: 0;
    pointer-events: none;
}
.sticky-cta {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    z-index: 40;
    animation: slideInUp 0.5s ease-out;
}
@keyframes slideInUp {
    from { transform: translateY(100px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}
::-webkit-scrollbar { display: none;}
